pub fn execute(operation:&str,input:&Json)->Result<Json,OlpError>{match operation{"derive_record_identity"=>{let rec=input.get("record").map_err(|e|OlpError::malformed("MALFORMED_INPUT",e))?;record::identity_output(rec)},"derive_record_commitment"=>{let rec=input.get("record").map_err(|e|OlpError::malformed("MALFORMED_INPUT",e))?;let alg=input.get_opt("algorithm").map_err(|e|OlpError::malformed("MALFORMED_INPUT",e))?.map(|v|v.as_i64()).transpose().map_err(|e|OlpError::malformed("MALFORMED_INPUT",e))?.unwrap_or(-16);let c=proof::commitment(rec,alg)?;let mut o=Json::object();o.insert("algorithm".into(),Json::Int(c.algorithm as i128));o.insert("digest_hex".into(),Json::String(util::hex_encode(&c.digest)));Ok(Json::Object(o))},"encode_proof_input"=>proof::encode_input_operation(input),"create_proof"=>proof::create_operation(input),"verify_proof"=>proof::verify_operation(input),"derive_proof_identity"=>proof_identity::proof_identity_operation(input),"encode_evidence_ref"=>evidence::encode_ref_operation(input),"process_relationship"=>evidence::process_relationship_operation(input),"process_bundle"=>bundle::process_bundle_operation(input),"resolve"=>resolution::resolve_operation(input),"evaluate_authority_lifecycle"=>identity_authority_lifecycle::evaluate_operation(input),"plan_disclosure"=>disclosure::plan_operation(input),_=>Err(OlpError::unsupported("UNSUPPORTED_OPERATION",operation))}}
